    cin >> A;
    if (A == 1) {
        cout << 1 << endl;
        return 0;
    }
    // Find all divisors of A
    for (long long i = 1; i * i <= A; ++i) {
        if (A % i == 0) {
            divisors.push_back(i);
            if (i != A / i) divisors.push_back(A / i);
        }
    }
    sort(divisors.begin(), divisors.end());
    long long count = 0;
    for (long long d : divisors) {
        if (d == A) continue;
        long long candidate = d;
        if (J(candidate) == A) {
            count++;
        }
