    vector<ll> divs = divisors(A);
    int m = divs.size();
    vector<vector<ll>> dp(m);
    dp[0].push_back(divs[0]);
    for (int i = 1; i < m; ++i) {
        for (ll d : dp[i - 1]) {
            if (divs[i] % d == 0) {
                dp[i].push_back(d);
            }
        }
        dp[i].push_back(divs[i]);
    }
    return dp[m - 1].size();
}

