long long sum_of_divisors(long long n) {
    if (n == 0) return 0;
    long long res = 1;
    long long temp = n;
    for (long long i = 2; i * i <= temp; i++) {
        if (temp % i == 0) {
            long long sum = 1;
            long long current = 1;
            while (temp % i == 0) {
                current *= i;
                sum += current;
                temp /= i;
            }
            res *= sum;
        }
    }
    if (temp > 1) {
        res *= (1 + temp);
    }
    return res;
}

